def script_header_names(path):
    """脚本文件头（第一行代码之前的注释块，含 `#!` 行）里写的弄坏开关变量名（形如 FOO_BREAK）；读不出交 None。"""
    header = []
    try:
        with open(path, encoding="utf-8") as handle:
            for line in handle:
                if line.strip() and not line.lstrip().startswith("#"):
                    break
                header.append(line)
    except (OSError, UnicodeDecodeError):
        return None
    return set(LIGHT_TIER_BREAK_NAME.findall("".join(header)))


def light_tier_break_variable(script_path, environment):
    """这条命令看得到的环境（命令前、env 里、前面 export 的）里设了（值非空）script_path 文件头写的弄坏开关变量，交第一个变量名；没设交 None。
    文件头读不出或一个名字都没有的，任何值非空的 `*_BREAK` 变量都算。带 --quick 的轻型在这种环境下不认（文件头「两档里的轻型」）。
    弄坏开关 light-tier-break-variable-ignored 下一律交 None。"""
    if break_is_set("light-tier-break-variable-ignored") or not environment:
        return None
    names = script_header_names(script_path)
    for name in sorted(environment):
        if environment[name] and (name in names if names else LIGHT_TIER_BREAK_NAME.fullmatch(name)):
            return name
    return None


